add_filter( 'woocommerce_my_account_my_orders_actions', 'perfectpixel_customer_confirm_action', 20, 2 );
add_action( 'template_redirect', 'perfectpixel_customer_confirm_handle' );

function perfectpixel_customer_confirm_action( $actions, $order ) {
	if ( $order->has_status( 'processing' ) ) {
		$actions['perfectpixel-confirm'] = array(
			'url'  => wp_nonce_url( add_query_arg( 'perfectpixel_confirm_order', $order->get_id(), wc_get_account_endpoint_url( 'orders' ) ), 'perfectpixel_confirm_order_' . $order->get_id() ),
			'name' => '{{confirm_order_label}}',
		);
	}
	return $actions;
}

function perfectpixel_customer_confirm_handle() {
	if ( empty( $_GET['perfectpixel_confirm_order'] ) || ! is_user_logged_in() ) {
		return;
	}
	$order_id = absint( $_GET['perfectpixel_confirm_order'] );
	if ( ! wp_verify_nonce( sanitize_key( $_GET['_wpnonce'] ?? '' ), 'perfectpixel_confirm_order_' . $order_id ) ) {
		return;
	}
	$order = wc_get_order( $order_id );
	if ( $order && (int) $order->get_customer_id() === get_current_user_id() && $order->has_status( 'processing' ) ) {
		$order->update_status( 'completed', 'Ο πελάτης επιβεβαίωσε την παραλαβή από τον λογαριασμό του.' );
		wc_add_notice( '{{confirm_order_notice}}' );
	}
	wp_safe_redirect( wc_get_account_endpoint_url( 'orders' ) );
	exit;
}
